       document.addEventListener(
           'DOMContentLoaded',
           function () {

               const quantityInput =
                   document.getElementById('vp_quantity');

               const quantityDisplay =
                   document.getElementById('vp_quantity_display');

               const totalAmount =
                   document.getElementById('vp_total_amount');

               const unitPrice =
                   parseFloat(
                       ''
                   ) || 0;


               function updateOrderTotal() {

                   let quantity =
                       parseInt(quantityInput.value) || 1;


                   quantityDisplay.textContent =
                       quantity;

                   totalAmount.textContent =
                       (unitPrice * quantity).toFixed(2);

               }


               quantityInput.addEventListener(
                   'input',
                   updateOrderTotal
               );

           }
       );

